#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> res;
    vector<int> freq(n + 2, 0);
    int cnt = 0, mex = 0, l = 0;

    for (int i = 0; i < n; ++i) {
        if (a[i] <= n) {
            if (freq[a[i]] == 0) cnt++;
            freq[a[i]]++;
        }
        while (freq[mex]) ++mex;
        if (cnt == mex) {
            res.push_back(mex);
            // reset for next subarray
            for (int j = l; j <= i; ++j) {
                if (a[j] <= n) {
                    freq[a[j]]--;
                    if (freq[a[j]] == 0) cnt--;
                }
            }
            l = i + 1;
            mex = 0;
        }
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}

#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> res;
    unordered_set<int> seen;
    int mex = 0, cnt = 0;
    vector<int> freq(n + 2, 0);

    for (int i = 0; i < n; ++i) {
        ++freq[a[i]];
        seen.insert(a[i]);
        while (seen.count(mex)) ++mex;
        if ((int)seen.size() == mex) {
            res.push_back(mex);
            seen.clear();
            mex = 0;
        }
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}

